declare(strict_types=1); namespace OCA\QuickMove\Controller; use OCP\AppFramework\Controller; use OCP\AppFramework\Http\DataResponse; use OCP\AppFramework\Http\Attribute\NoAdminRequired; use OCP\Files\IRootFolder; use OCP\Files\Folder; use OCP\Files\File; use OCP\Files\NotFoundException; use OCP\IConfig; use OCP\IRequest; use OCP\IUserSession; class QuickMoveController extends Controller { private const CONFIG_KEY = "quickmove_destinations"; public function __construct( string $appName, IRequest $request, private IRootFolder $rootFolder, private IUserSession $userSession, private IConfig $config, ) { parent::__construct($appName, $request); } #[NoAdminRequired] public function getDestinations(): DataResponse { $user = $this->userSession->getUser(); if (!$user) { return new DataResponse(["error" => "Unauthenticated"], 401); } $raw = $this->config->getUserValue($user->getUID(), $this->appName, self::CONFIG_KEY, "[]"); $destinations = json_decode($raw, true) ?: []; return new DataResponse([ "success" => true, "destinations" => $destinations, ]); } #[NoAdminRequired] public function saveDestinations(array $destinations): DataResponse { $user = $this->userSession->getUser(); if (!$user) { return new DataResponse(["error" => "Unauthenticated"], 401); } $cleaned = []; foreach ($destinations as $item) { $path = trim((string)($item["path"] ?? ""), "/"); $name = trim((string)($item["name"] ?? "")); if ($path === "" && $name === "") { continue; } if ($name === "") { $name = basename($path) . " へ移動"; } $cleaned[] = [ "id" => (string)($item["id"] ?? uniqid("qm_")), "name" => $name, "path" => "/" . $path, ]; } $this->config->setUserValue($user->getUID(), $this->appName, self::CONFIG_KEY, json_encode($cleaned)); return new DataResponse([ "success" => true, "destinations" => $cleaned, ]); } #[NoAdminRequired] public function move(array $items, string $destFolderPath): DataResponse { $user = $this->userSession->getUser(); if (!$user) { return new DataResponse(["error" => "Unauthenticated"], 401); } $userFolder = $this->rootFolder->getUserFolder($user->getUID()); try { $destPath = trim($destFolderPath, "/"); $destFolder = ($destPath === "") ? $userFolder : $userFolder->get($destPath); if (!$destFolder instanceof Folder) { return new DataResponse(["error" => "移動先がフォルダではありません"], 400); } $movedCount = 0; $errors = []; foreach ($items as $item) { $targetId = (int)($item["targetId"] ?? 0); $targetPath = (string)($item["targetPath"] ?? ""); $sourceNode = null; if ($targetId > 0) { $nodes = $userFolder->getById($targetId); if (!empty($nodes)) { $sourceNode = $nodes[0]; } } if ($sourceNode === null && $targetPath !== "") { try { $sourceNode = $userFolder->get(ltrim($targetPath, "/")); } catch (NotFoundException) {} } if ($sourceNode === null) { $errors[] = "ノードが見つかりません: " . ($targetPath ?: (string)$targetId); continue; } if ($sourceNode instanceof Folder) { $sourcePathSlash = rtrim($sourceNode->getPath(), "/") . "/"; $destPathSlash = rtrim($destFolder->getPath(), "/") . "/"; if (str_starts_with($destPathSlash, $sourcePathSlash)) { $errors[] = "フォルダ自身またはそのサブフォルダへは移動できません: " . $sourceNode->getName(); continue; } } if ($sourceNode->getParent()->getId() === $destFolder->getId()) { $errors[] = "既に同じフォルダ内に存在します: " . $sourceNode->getName(); continue; } $targetFileName = $sourceNode->getName(); $baseName = pathinfo($targetFileName, PATHINFO_FILENAME); $ext = pathinfo($targetFileName, PATHINFO_EXTENSION); $candidateName = $targetFileName; $counter = 1; while ($destFolder->nodeExists($candidateName)) { if ($sourceNode instanceof Folder || empty($ext)) { $candidateName = "{$baseName} ({$counter})"; } else { $candidateName = "{$baseName} ({$counter}).{$ext}"; } $counter++; } $newTargetInternalPath = $destFolder->getPath() . "/" . $candidateName; $sourceNode->move($newTargetInternalPath); $movedCount++; } return new DataResponse([ "success" => true, "movedCount" => $movedCount, "errors" => $errors, "destFolderPath" => "/" . ltrim($destFolder->getName(), "/"), ]); } catch (\Exception $e) { return new DataResponse(["error" => $e->getMessage()], 500); } } }